def eval_rpn(tokens: list[str]) -> int:
    stack: list[int] = []

    for token in tokens:
        if token in ("+", "-", "*", "/"):
            right = stack.pop()
            left = stack.pop()

            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            else:
                sign = -1 if (left < 0) ^ (right < 0) else 1
                result = sign * (abs(left) // abs(right))

            stack.append(result)
        else:
            stack.append(int(token))

    return stack[-1]
