import heapq


def shortest_paths(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    graph = [[] for _ in range(n)]

    for u, v, w in edges:
        graph[u].append((v, w))

    INF = float("inf")
    dist = [INF] * n

    if 0 <= src < n:
        dist[src] = 0

    heap = [(0, src)] if 0 <= src < n else []

    while heap:
        d, u = heapq.heappop(heap)

        if d != dist[u]:
            continue

        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))

    return [d if d != INF else -1 for d in dist]
```

