def decode_string(s: str) -> str:
    stack = []
    current = []
    count = 0

    for ch in s:
        if ch.isdigit():
            count = count * 10 + int(ch)
        elif ch == "[":
            stack.append((current, count))
            current = []
            count = 0
        elif ch == "]":
            previous, repeat = stack.pop()
            current = previous + ["".join(current) * repeat]
        else:
            current.append(ch)

    return "".join(current)
