def moving_average(xs: list[float], k: int) -> list[float]:
    out = []
    total = 0
    for i in range(len(xs)):
        total += xs[i]
        if i >= k:
            total -= xs[i - k]
        if i >= k - 1:
            out.append(total / k)
    return out
